validator:
function validate([n]) {
  if (n < 1 || n > 1e15) return 'n is from 1 to 10^15.';
  return null;
}

reference:
function maxNumber(n) {
  let value = BigInt(n);
  let trimmed = value & (value - 1n);
  while (trimmed !== 0n) {
    value = trimmed;
    trimmed = value & (value - 1n);
  }
  const answer = value - 1n;
  return Number(answer);
}

brute:
function maxNumber(n) {
  // Grow the range [x, n] downward one number at a time until its AND becomes 0.
  let x = BigInt(n);
  let and = x;
  while (and !== 0n) {
    x -= 1n;
    and &= x;
  }
  return Number(x);
}

generator:
function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const shape = rand();
  if (size === 'small') {
    if (shape < 0.4) return [pick(1, 300)];
    // Just above a power of two the brute force needs only a few steps, even for a huge n.
    if (shape < 0.8) {
      const power = 2 ** pick(0, 49);
      return [power + pick(0, Math.min(power - 1, 40))];
    }
    return [2 ** pick(1, 14) - 1];
  }
  if (shape < 0.25) return [1e15];
  if (shape < 0.5) return [2 ** pick(32, 49) - 1];
  if (shape < 0.75) return [2 ** pick(32, 49) + pick(0, 1000)];
  return [pick(2 ** 32, 1e15)];
}
